<style>
:root{--bg:#080d17;--sidebar:#0b111e;--card:#0e1625;--card2:#111c2d;--line:rgba(152,177,220,.14);--text:#edf3ff;--muted:#91a1bb;--blue:#4a8aff;--cyan:#5be3ed;--green:#80e0b5;--amber:#f3c879}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px 'DM Sans',sans-serif;min-height:100vh}a{color:inherit;text-decoration:none}button{font:inherit}.app{min-height:100vh;display:grid;grid-template-columns:236px minmax(0,1fr)}.sidebar{background:var(--sidebar);border-right:1px solid var(--line);padding:23px 14px;display:flex;flex-direction:column}.brand{display:flex;align-items:center;gap:10px;padding:0 9px 28px;font:700 17px 'Space Grotesk',sans-serif;letter-spacing:.13em}.mark{width:30px;height:34px;color:var(--cyan)}.brand small{display:block;font:500 8px 'DM Sans',sans-serif;letter-spacing:.15em;color:#7e91b1;margin-top:1px}.navlabel{padding:13px 11px 8px;color:#5f718f;font-size:9px;font-weight:700;letter-spacing:.15em;text-transform:uppercase}.navitem{display:flex;align-items:center;gap:12px;padding:11px;border-radius:10px;color:#8e9fba;margin:2px 0;font-size:12px}.navitem svg{width:17px;height:17px;opacity:.85}.navitem.active{background:rgba(65,127,255,.14);border:1px solid rgba(65,127,255,.17);color:#dfeaff}.navitem.active svg{color:#76a8ff}.sidebar-bottom{margin-top:auto}.profile{border-top:1px solid var(--line);padding:17px 8px 0;display:flex;align-items:center;gap:10px}.avatar{width:34px;height:34px;display:grid;place-items:center;border-radius:11px;background:linear-gradient(135deg,#2859a9,#15314e);color:#d9f7ff;font-weight:700}.profile b{font-size:11px;display:block}.profile span{font-size:10px;color:var(--muted)}.main{min-width:0}.top{height:69px;display:flex;align-items:center;justify-content:space-between;padding:0 32px;border-bottom:1px solid var(--line);background:rgba(8,13,23,.8)}.crumb{font-size:11px;color:#8293ae}.crumb b{color:#e8efff;font-weight:600}.top-right{display:flex;align-items:center;gap:13px}.demo-pill{display:inline-flex;align-items:center;gap:7px;padding:7px 10px;border-radius:8px;color:#f4d391;background:rgba(243,200,121,.08);border:1px solid rgba(243,200,121,.2);font-size:10px}.dot{width:6px;height:6px;border-radius:50%;background:var(--amber)}.iconbtn{width:34px;height:34px;border:1px solid var(--line);border-radius:10px;background:transparent;color:#a8b7cf}.content{padding:30px 32px 45px;max-width:1500px;margin:auto}.pagehead{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:24px}.eyebrow{font-size:10px;color:var(--cyan);font-weight:700;letter-spacing:.14em;text-transform:uppercase;margin-bottom:8px}.pagehead h1{font:600 29px 'Space Grotesk',sans-serif;letter-spacing:-.04em;margin:0 0 8px}.pagehead p{margin:0;color:var(--muted);font-size:12px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid var(--line);border-radius:10px;padding:10px 13px;background:var(--card2);color:#dce7fb;font-size:11px;font-weight:600;white-space:nowrap}.btn-primary{background:linear-gradient(110deg,#4387ff,#2861dd);border-color:#4784f0;color:white}.notice{display:flex;align-items:flex-start;gap:12px;border:1px solid rgba(243,200,121,.2);background:rgba(243,200,121,.055);padding:13px 15px;border-radius:12px;margin-bottom:22px}.notice-icon{color:var(--amber);font-size:17px}.notice b{display:block;font-size:11px;color:#f4d391;margin-bottom:3px}.notice p{margin:0;font-size:11px;line-height:1.6;color:#b6b3a7}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}.stat,.panel{background:linear-gradient(145deg,rgba(16,25,42,.9),rgba(12,19,32,.94));border:1px solid var(--line);border-radius:14px}.stat{padding:17px}.stat-top{display:flex;align-items:center;justify-content:space-between;color:#94a4bf;font-size:10px}.stat-icon{width:31px;height:31px;border-radius:9px;display:grid;place-items:center;background:rgba(73,138,255,.11);color:#7fb0ff}.stat-icon svg{width:17px;height:17px}.stat-value{font:600 27px 'Space Grotesk',sans-serif;margin:15px 0 5px;letter-spacing:-.04em}.stat-foot{font-size:10px;color:#8798b3}.muted-tag{color:#7c8eaa}.dashboard-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(270px,.85fr);gap:16px}.panel{padding:19px;margin-bottom:16px}.panel-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:18px}.panel-head h2{font:600 14px 'Space Grotesk',sans-serif;margin:0}.panel-head a,.small-action{font-size:10px;color:#7faeff}.panel-sub{font-size:10px;color:#8192ad;margin-top:5px}.chart-area{height:190px;position:relative}.chart-area svg{width:100%;height:100%;overflow:visible}.gridline{stroke:rgba(144,167,208,.12);stroke-width:1}.line-blue{fill:none;stroke:#548cff;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}.line-cyan{fill:none;stroke:#5be3ed;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;opacity:.8}.legend{display:flex;gap:16px;color:#8b9cb6;font-size:10px}.legend i{display:inline-block;width:7px;height:7px;border-radius:50%;background:#548cff;margin-right:6px}.legend .cyan{background:#5be3ed}.list{display:grid;gap:0}.listrow{display:flex;align-items:center;gap:11px;padding:13px 0;border-top:1px solid var(--line)}.listrow:first-child{border-top:0;padding-top:0}.row-icon{width:34px;height:34px;border:1px solid var(--line);border-radius:10px;display:grid;place-items:center;color:#85b3ff;background:rgba(70,128,235,.08);font-size:15px}.row-main{flex:1;min-width:0}.row-main b{display:block;font-size:11px;font-weight:600}.row-main span{display:block;font-size:10px;color:#8495b0;margin-top:4px}.status{font-size:9px;border-radius:7px;padding:5px 7px;white-space:nowrap}.status.pending{color:#f3cd86;background:rgba(243,200,121,.09)}.status.ready{color:#8fe0b8;background:rgba(127,224,178,.08)}.status.neutral{color:#9bb0cf;background:rgba(139,165,209,.09)}.empty-chart{display:flex;align-items:center;justify-content:center;position:absolute;inset:0;color:#6e809d;font-size:10px;background:linear-gradient(180deg,transparent,rgba(7,12,21,.2))}.policy-row{display:grid;grid-template-columns:1fr auto;gap:8px;padding:12px 0;border-top:1px solid var(--line)}.policy-row:first-of-type{border-top:0}.policy-row b{display:block;font-size:11px}.policy-row span{display:block;color:#8596b1;font-size:10px;margin-top:4px}.policy-footer{border-top:1px solid var(--line);padding-top:13px;margin-top:8px}.policy-footer a{font-size:10px;color:#80adff}.quicklinks{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.quicklink{border:1px solid var(--line);border-radius:12px;padding:15px;background:rgba(255,255,255,.012);transition:border-color .2s}.quicklink:hover{border-color:rgba(91,227,237,.35)}.quicklink .qicon{font-size:18px;color:var(--cyan);margin-bottom:13px}.quicklink b{display:block;font-size:11px;margin-bottom:5px}.quicklink span{font-size:10px;color:#8798b3;line-height:1.5;display:block}.footnote{font-size:10px;color:#667895;text-align:center;margin-top:17px}.mobile-brand{display:none}
@media(max-width:1080px){.app{grid-template-columns:205px minmax(0,1fr)}.content{padding:25px 22px}.top{padding:0 22px}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.dashboard-grid{grid-template-columns:1fr}.right-col{display:grid;grid-template-columns:1fr 1fr;gap:14px}.right-col .panel{height:fit-content}}
@media(max-width:680px){.app{display:block}.sidebar{display:none}.top{height:59px;padding:0 15px}.mobile-brand{display:flex;align-items:center;gap:8px;font:700 14px 'Space Grotesk',sans-serif;letter-spacing:.1em}.mobile-brand svg{width:23px;height:27px;color:var(--cyan)}.crumb{display:none}.content{padding:23px 15px 35px}.pagehead{flex-direction:column}.pagehead h1{font-size:26px}.pagehead .btn{width:100%}.stats{gap:10px}.stat{padding:13px}.stat-value{font-size:24px}.stat-top{font-size:9px}.stat-foot{font-size:9px}.right-col{display:block}.panel{padding:15px}.chart-area{height:150px}.quicklinks{grid-template-columns:1fr}.quicklink{display:flex;gap:13px;align-items:center;padding:13px}.quicklink .qicon{margin:0;width:25px}.demo-pill{font-size:9px}.top-right{gap:8px}}
</style>
</head>
